package com.library.circulation;

import com.fasterxml.jackson.databind.JsonNode;
import com.library.security.JwtTokenProvider;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.HttpMethod;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.context.ActiveProfiles;
import org.springframework.test.web.servlet.MockMvc;

import java.nio.file.*;
import java.util.*;
import static com.library.circulation.CirculationSupport.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

@SpringBootTest(properties="spring.datasource.url=jdbc:h2:mem:circulation_http;DB_CLOSE_DELAY=-1;MODE=MYSQL")
@AutoConfigureMockMvc
@ActiveProfiles("test")
class CirculationControllerTest {
    @Autowired MockMvc mvc;@Autowired JdbcTemplate jdbc;@Autowired JwtTokenProvider jwt;
    long clerk,reader;String staffToken,readerToken;
    private static final List<JsonNode> CAPTURES=new ArrayList<>();
    @BeforeEach void setup(){clerk=user("LIBRARIAN");reader=user("READER");staffToken=token(clerk,"LIBRARIAN");readerToken=token(reader,"READER");}
    long user(String role){String n=UUID.randomUUID().toString();jdbc.update("INSERT INTO sys_user(username,password,real_name,role,status) VALUES (?,'synthetic-only',NULL,?,1)",n,role);return jdbc.queryForObject("SELECT id FROM sys_user WHERE username=?",Long.class,n);}
    String token(long id,String role){return jwt.generateToken(id,"synthetic",role,0L);}
    String base(String key){return "/circulation/requests/"+key;}
    JsonNode call(String method,String url,String body,String token,int status)throws Exception{var req=request(HttpMethod.valueOf(method),url).header("Authorization","Bearer "+token).contentType("application/json");if(body!=null)req.content(body);var result=mvc.perform(req).andExpect(status().is(status)).andReturn();JsonNode out=read(result.getResponse().getContentAsString(java.nio.charset.StandardCharsets.UTF_8));CAPTURES.add(obj("method",method,"path",url,"requestBodyUtf8",body,"status",status,"body",out));return out;}
    JsonNode input(){String isbn=UUID.randomUUID().toString().replace("-","").substring(0,20);jdbc.update("INSERT INTO book(isbn,title,stock_total,stock_available,status) VALUES (?,'合成协议图书',1,1,1)",isbn);long b=jdbc.queryForObject("SELECT id FROM book WHERE isbn=?",Long.class,isbn);jdbc.update("INSERT INTO book_copy(book_id,barcode,status) VALUES (?,?,'AVAILABLE')",b,"000Aa<script>原文</script> "+UUID.randomUUID());long c=jdbc.queryForObject("SELECT id FROM book_copy WHERE book_id=?",Long.class,b);return obj("operation","BORROW","userId",reader,"items",List.of(obj("bookId",b,"copyId",c,"borrowDays",30)),"remark","<script>文字</script> drop table books; /* literal */");}
    @Test void exactJsonContractAndNullNamesAndDerivedListFiltersAndCancellationAreServed()throws Exception{String key=UUID.randomUUID().toString();JsonNode in=input();JsonNode p=call("POST",base(key)+"/preview",write(in),staffToken,200).path("data");assertTrue(p.path("preview").path("borrower").path("userName").isNull());assertEquals(in.path("remark"),p.path("input").path("remark"));JsonNode receipt=call("POST",base(key)+"/confirm",write(obj("previewDigest",p.get("previewDigest"))),staffToken,200).path("data");long order=receipt.path("orderId").asLong();assertEquals(1,call("GET","/circulation/orders?userId="+reader+"&state=BORROWING",null,staffToken,200).path("data").path("total").asInt());assertTrue(call("GET","/circulation/orders/"+order,null,staffToken,200).path("data").path("userName").isNull());assertEquals(receipt,call("GET",base(key),null,staffToken,200).path("data").get("receipt"));String ret=UUID.randomUUID().toString();JsonNode rp=call("POST",base(ret)+"/preview",write(obj("operation","RETURN","recordIds",List.of(receipt.path("items").get(0).path("recordId")),"remark","")),staffToken,200).path("data");call("POST",base(ret)+"/confirm",write(obj("previewDigest",rp.get("previewDigest"))),staffToken,200);assertEquals("RETURNED",call("GET","/circulation/orders/"+order,null,staffToken,200).path("data").path("state").asText());String cancelled=UUID.randomUUID().toString();assertEquals("CANCELLED",call("POST",base(cancelled)+"/cancel","{}",staffToken,200).path("data").path("state").asText());assertEquals("REQUEST_CANCELLED",call("POST",base(cancelled)+"/preview",write(in),staffToken,409).path("data").path("reasonCode").asText());}
    @Test void duplicateUnknownUnsafeCoercedAndTrailingJsonAreRejectedWithoutCreatingRequests()throws Exception{String[] invalid={"{\"operation\":\"RETURN\",\"recordIds\":[1],\"remark\":\"\",\"remark\":\"x\"}","{\"operation\":\"RETURN\",\"recordIds\":[1],\"remark\":\"\",\"x\":0}","{\"operation\":\"RETURN\",\"recordIds\":[1.0],\"remark\":\"\"}","{\"operation\":\"RETURN\",\"recordIds\":[true],\"remark\":\"\"}","{\"operation\":\"RETURN\",\"recordIds\":[\"1\"],\"remark\":\"\"}","{\"operation\":\"RETURN\",\"recordIds\":[9007199254740992],\"remark\":\"\"}","{\"operation\":\"RETURN\",\"recordIds\":[1,1],\"remark\":\"\"}","{\"operation\":\"RETURN\",\"recordIds\":[],\"remark\":\"\"}","{} {}","[]","null","{\"operation\":\"BORROW\",\"userId\":1,\"items\":[{\"bookId\":1,\"bookId\":2,\"copyId\":1,\"borrowDays\":30}],\"remark\":\"\"}","{\"operation\":\"RETURN\",\"recordIds\":[1],\"remark\":\"\\ud800\"}"};for(String s:invalid)assertEquals("INVALID_INPUT",call("POST",base(UUID.randomUUID().toString())+"/preview",s,staffToken,400).path("data").path("reasonCode").asText());assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM circulation_request WHERE actor_id=?",Integer.class,clerk));}
    @Test void currentRolePrecedesBodyPathAndQueryAndBoundedLiteralInputDoesNotChangeOtherRoutes()throws Exception{String path=base("not-a-uuid")+"/preview";assertEquals("ROLE_REQUIRED",call("POST",path+"?unknown=' or 1=1--","bad".repeat(20000),readerToken,403).path("data").path("reasonCode").asText());assertEquals("BODY_TOO_LARGE",call("POST",base(UUID.randomUUID().toString())+"/preview"," ".repeat(32769),staffToken,413).path("data").path("reasonCode").asText());call("GET","/circulation/orders?page=1&page=2",null,staffToken,400);call("GET","/circulation/orders?keyword=abc",null,staffToken,400);call("GET","/circulation/orders/9007199254740992",null,staffToken,400);mvc.perform(post(base(UUID.randomUUID().toString())+"/cancel").header("Authorization","Bearer "+staffToken).contentType("text/plain").content("{}")).andExpect(status().isBadRequest());mvc.perform(get("/borrows?keyword=' or 1=1--").header("Authorization","Bearer "+staffToken)).andExpect(status().isBadRequest());}
    @Test void unknownRequest404DoesNotPermitLatePreviewAfterExplicitCancelAndOwnerIsChecked()throws Exception{String key=UUID.randomUUID().toString();assertEquals("REQUEST_NOT_FOUND",call("GET",base(key),null,staffToken,404).path("data").path("reasonCode").asText());call("POST",base(key)+"/cancel","{}",staffToken,200);long other=user("ADMIN");assertEquals("OWNER_REQUIRED",call("GET",base(key),null,token(other,"ADMIN"),403).path("data").path("reasonCode").asText());}
    @Test void nonUtf8WireBytesAndCancelledPreviewAreNotSilentlyDecodedOrRevived()throws Exception{for(byte[] b:List.of(new byte[]{'{','"','x','"',':','"',(byte)0xc3,'"','}'},"{}".getBytes(java.nio.charset.StandardCharsets.UTF_16LE)))mvc.perform(post(base(UUID.randomUUID().toString())+"/cancel").header("Authorization","Bearer "+staffToken).contentType("application/json").content(b)).andExpect(status().isBadRequest()).andExpect(jsonPath("$.data.reasonCode").value("INVALID_INPUT"));String k=UUID.randomUUID().toString();JsonNode in=input();call("POST",base(k)+"/preview",write(in),staffToken,200);JsonNode cancelled=call("POST",base(k)+"/cancel","{}",staffToken,200).path("data");assertEquals(cancelled,call("POST",base(k)+"/preview",write(in),staffToken,200).path("data"));}
    @Test void staffCannotBeBorrowTargetAndChangedBorrowerRoleCannotConfirmButCanReturnHistory()throws Exception{for(String role:List.of("ADMIN","LIBRARIAN")){long target=user(role);var in=input().deepCopy();((com.fasterxml.jackson.databind.node.ObjectNode)in).put("userId",target);assertEquals("MEMBER_NOT_FOUND",call("POST",base(UUID.randomUUID().toString())+"/preview",write(in),staffToken,404).path("data").path("reasonCode").asText());}String key=UUID.randomUUID().toString();JsonNode p=call("POST",base(key)+"/preview",write(input()),staffToken,200).path("data");jdbc.update("UPDATE sys_user SET role='ADMIN' WHERE id=?",reader);assertEquals("PREVIEW_STALE",call("POST",base(key)+"/confirm",write(obj("previewDigest",p.get("previewDigest"))),staffToken,409).path("data").path("reasonCode").asText());}
    @AfterAll static void saveCaptures()throws Exception{Path path=Path.of("target","circulation-h2-http-captures.json");Files.createDirectories(path.getParent());Files.writeString(path,write(CAPTURES));}
}
